--
-- Name: fn_count_etablissements_groupe(uuid); Type: FUNCTION; Schema: public; Owner: elisaschool_user
--

CREATE FUNCTION public.fn_count_etablissements_groupe(p_groupe_id uuid) RETURNS integer
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN (
        SELECT COUNT(*)
        FROM groupe_etablissement_liens
        WHERE "groupeId" = p_groupe_id
    );
END;
$$;


ALTER FUNCTION public.fn_count_etablissements_groupe(p_groupe_id uuid) OWNER TO elisaschool_user;

--
-- Name: FUNCTION fn_count_etablissements_groupe(p_groupe_id uuid); Type: COMMENT; Schema: public; Owner: elisaschool_user
--

COMMENT ON FUNCTION public.fn_count_etablissements_groupe(p_groupe_id uuid) IS 'Compte le nombre d''établissements dans un groupe';


--
-- Name: fn_update_maj_at(); Type: FUNCTION; Schema: public; Owner: elisaschool_user
--

CREATE FUNCTION public.fn_update_maj_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.maj_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_update_maj_at() OWNER TO elisaschool_user;

--
-- Name: fn_user_has_groupe_access(uuid, uuid); Type: FUNCTION; Schema: public; Owner: elisaschool_user
--

CREATE FUNCTION public.fn_user_has_groupe_access(p_groupe_id uuid, p_utilisateur_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1
        FROM groupes_etablissements g
        LEFT JOIN groupe_admins ga ON g.id = ga."groupeId"
        WHERE g.id = p_groupe_id
            AND g.actif = TRUE
            AND (
                g."proprietaireId" = p_utilisateur_id
                OR ga."utilisateurId" = p_utilisateur_id
            )
    );
END;
$$;


ALTER FUNCTION public.fn_user_has_groupe_access(p_groupe_id uuid, p_utilisateur_id uuid) OWNER TO elisaschool_user;

--
-- Name: FUNCTION fn_user_has_groupe_access(p_groupe_id uuid, p_utilisateur_id uuid); Type: COMMENT; Schema: public; Owner: elisaschool_user
--

COMMENT ON FUNCTION public.fn_user_has_groupe_access(p_groupe_id uuid, p_utilisateur_id uuid) IS 'Vérifie si un utilisateur a accès à un groupe (propriétaire ou admin)';


--
-- Name: nettoyer_anciennes_tentatives(); Type: FUNCTION; Schema: public; Owner: elisaschool_user
--

CREATE FUNCTION public.nettoyer_anciennes_tentatives() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    nb_supprimes INTEGER;
BEGIN
    DELETE FROM tentatives_connexion
    WHERE "derniereTentative" < NOW() - INTERVAL '24 hours'
    AND ("bloqueJusqua" IS NULL OR "bloqueJusqua" < NOW());
    
    GET DIAGNOSTICS nb_supprimes = ROW_COUNT;
    
    RETURN nb_supprimes;
END;
$$;


ALTER FUNCTION public.nettoyer_anciennes_tentatives() OWNER TO elisaschool_user;

--
-- Name: FUNCTION nettoyer_anciennes_tentatives(); Type: COMMENT; Schema: public; Owner: elisaschool_user
--

COMMENT ON FUNCTION public.nettoyer_anciennes_tentatives() IS 'Supprime les tentatives de connexion de plus de 24h';


